// Ambas lecturas llegan vía $input.all() — diferenciamos por campos
// BLOGS_SITES_CONFIG: tiene ID_BLOG pero NO tiene STATUS
// CONTENT_PIPELINE: tiene STATUS
const allItems = $input.all().map(i => i.json);
const allBlogs = allItems.filter(i => i.ID_BLOG && i.STATUS === undefined);
const existingRows = allItems.filter(i => i.STATUS !== undefined);

if (allBlogs.length === 0) {
  return [{ json: { _skip: true, reason: 'No se encontraron blogs en BLOGS_SITES_CONFIG' } }];
}

// Anti-canibalización: set de títulos existentes
const existingTitles = new Set(
  existingRows.filter(r => r.TEMA_ARTICULO).map(r => r.TEMA_ARTICULO.toLowerCase().trim())
);

// Conteo de PENDING por blog
const pendingByBlog = {};
existingRows.filter(r => String(r.STATUS ?? '') === 'PENDING').forEach(r => {
  pendingByBlog[r.ID_BLOG] = (pendingByBlog[r.ID_BLOG] || 0) + 1;
});

const now = new Date();
const dateStr = now.toISOString().slice(0,10).replace(/-/g,'');
const lastIdx = existingRows.length + 1;

// HIGH_RPM niches — prioridad para Adsense (buyer intent, micronichos)
const HIGH_RPM = ['abogad','impuest','legal','segur','accidente','multa','bienes','hipotec','salud','médic','insurance','lawyer','tax','accident'];
const isHighRpm = (nicho) => HIGH_RPM.some(k => (nicho||'').toLowerCase().includes(k));

// Umbral agresivo: procesar blogs con < 100 artículos pendientes
const PENDING_THRESHOLD = 100;
const MAX_BLOGS_PER_RUN = 10;
const TITLES_PER_BLOG = 50;

const validBlogs = allBlogs.filter(b => b.ID_BLOG);
const blogsNeedingTitles = validBlogs
  .filter(b => (pendingByBlog[b.ID_BLOG] || 0) < PENDING_THRESHOLD)
  .sort((a, b) => {
    const aRpm = isHighRpm(a.NICHO) ? 0 : 1;
    const bRpm = isHighRpm(b.NICHO) ? 0 : 1;
    if (aRpm !== bRpm) return aRpm - bRpm;
    return (pendingByBlog[a.ID_BLOG]||0) - (pendingByBlog[b.ID_BLOG]||0);
  })
  .slice(0, MAX_BLOGS_PER_RUN);

if (blogsNeedingTitles.length === 0) {
  return [{ json: { _skip: true, reason: 'Todos los blogs superan ' + PENDING_THRESHOLD + ' pendientes' } }];
}

return blogsNeedingTitles.map((blog, idx) => ({
  json: {
    blogId: blog.ID_BLOG,
    sitioUrl: blog.SITIO_URL || '',
    nicho: blog.NICHO || 'general',
    idioma: blog.IDIOMA || 'es',
    bloggerId: blog.BLOGGER_ID || '',
    isHighRpm: isHighRpm(blog.NICHO),
    existingTitles: Array.from(existingTitles).slice(0, 30),
    titlesPerBlog: TITLES_PER_BLOG,
    startIndex: lastIdx + (idx * TITLES_PER_BLOG),
    dateStr,
    pendingCount: pendingByBlog[blog.ID_BLOG] || 0
  }
}));

