const res = $('Generar Títulos DeepSeek').item.json;
const prev = $('Preparar por Blog').item.json;

if (!res.choices || !res.choices[0]) {
  throw new Error('DeepSeek sin respuesta: ' + JSON.stringify(res).substring(0,200));
}

let titlesData;
try {
  const content = res.choices[0].message.content;
  const clean = content.replace(/^```json\s*/i,'').replace(/^```\s*/i,'').replace(/\s*```\s*$/i,'').trim();
  titlesData = JSON.parse(clean);
} catch(e) {
  throw new Error('JSON inválido de DeepSeek: ' + e.message);
}

const titles = titlesData.titles || [];
if (titles.length === 0) throw new Error('DeepSeek retornó lista vacía');

const existingSet = new Set(prev.existingTitles.map(t => t.toLowerCase().trim()));
const now = new Date().toISOString();
const dateStr = prev.dateStr;

const rows = [];
for (const t of titles) {
  const titleLower = (t.title||'').toLowerCase().trim();
  if (!t.title || existingSet.has(titleLower)) continue;
  existingSet.add(titleLower);
  const uid = `TF${dateStr}-${prev.blogId.substring(0,6).replace(/[^a-z0-9]/gi,'')}-${Date.now().toString(36).slice(-4)}-${Math.random().toString(36).slice(2,5)}`;
  rows.push({
    ID_UNICO: uid,
    STATUS: 'PENDING',
    LOCK: 'FALSE',
    ID_BLOG: prev.blogId,
    KEYWORD: t.keywords || t.title.split(' ').slice(0,4).join(' '),
    TEMA_ARTICULO: t.title,
    ID_PARENT_SILO: '',
    PRIORITY: String(t.priority || 2),
    RETRY_COUNT: '0'
  });
}

if (rows.length === 0) throw new Error('Todos los títulos ya existen');

return rows.map(r => ({ json: r }));
